input.newString:
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const forge = require("node-forge");

const APP = __dirname;
const SAMPLES = path.join(APP, "samples");
const manifest = JSON.parse(fs.readFileSync(path.join(SAMPLES, "manifest.json"), "utf8"));

// Strict PKCS#1 v1.5 verification via OpenSSL. node-forge 1.3.1 has a known
// RSA PKCS#1 v1.5 signature-verification flaw (CVE-2022-24771/24772/24773)
// that is exploitable against low-exponent (e=3) keys, allowing signature
// forgery without the private key. Since this service accepts documents and
// detached signatures from external partners, a forged submission could be
// marked VALID. We therefore require BOTH forge and OpenSSL's strict verifier
// to agree before accepting. Every legitimate (genuinely signed) document —
// including the historical e=3 partner-root documents — passes strict
// verification, so this preserves all valid results while rejecting forgeries.
function verifyStrict(pubPem, bodyBuf, sigBuf) {
  try {
    return crypto.verify(
      "RSA-SHA256",
      bodyBuf,
      { key: pubPem, padding: crypto.constants.RSA_PKCS1_PADDING },
      sigBuf
    );
  } catch (err) {
    return false;
  }
}

let ok = 0;
let fail = 0;
for (const e of manifest.entries) {
  const pubPem = fs.readFileSync(path.join(SAMPLES, e.pubkey), "utf8");
  const bodyStr = fs.readFileSync(path.join(SAMPLES, e.doc), "utf8");
  const bodyBuf = fs.readFileSync(path.join(SAMPLES, e.doc));
  const sigB64 = fs.readFileSync(path.join(SAMPLES, e.sig), "utf8").trim();
  const sig = forge.util.decode64(sigB64);
  const sigBuf = Buffer.from(sigB64, "base64");

  const pub = forge.pki.publicKeyFromPem(pubPem);
  const md = forge.md.sha256.create();
  md.update(bodyStr, "utf8");

  let forgeValid = false;
  try {
    forgeValid = pub.verify(md.digest().bytes(), sig);
  } catch (err) {
    forgeValid = false;
  }
  const strictValid = verifyStrict(pubPem, bodyBuf, sigBuf);
  const valid = forgeValid && strictValid;

  if (valid) ok++;
  else fail++;
  const note = forgeValid && !strictValid ? " REJECTED-BY-STRICT-VERIFIER" : "";
  console.log(`${valid ? "VALID  " : "INVALID"}  ${e.id}  key=${e.key} (e=${e.exponent})${note}`);
}

